## Code Example

```javascript
// Minimal token bucket sketch (pseudo-C style in JS-like syntax for readability)
typedef struct { atomic_uint tokens; uint32_t bucket; uint32_t rate; spinlock_t lock; wait_queue_t wq; } tb_t;
bool io_submit(tb_t *tb, size_t size) {
  if (atomic_read(&tb->tokens) >= size) {
    atomic_sub(&tb->tokens, size);
    submit_to_device(size);
    return true;
  }
  enqueue_io(size);
  return false;
}
void refill(tb_t *tb) {
  uint32_t t = atomic_read(&tb->tokens) + tb->rate;
  if (t > tb->bucket) t = tb->bucket;
  atomic_write(&tb->tokens, t);
  wake_up(&tb->wq);
}
```

